-- Date: 2026-02-28
-- Topic: Written Representations
-- Difficulty: 9E / 15M / 6H
-- Bloom's: L1:8 / L2:9 / L3:8 / L4:5

BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: medium / L3 — Effect of management turnover on representation letter
(1, 'Written Representations', 'During the audit of Northfield Energy Corp. for the year ended December 31, 2025, the CEO who oversaw operations for the entire fiscal year resigned on February 15, 2026. The new CEO, who started on March 1, 2026, is asked to sign the management representation letter. The engagement partner at Crane & Associates must assess the effect on the representations. What is the most likely implication for the auditor?', '["The auditor cannot obtain a valid representation letter because the new CEO did not oversee the fiscal year", "The auditor should evaluate whether the new CEO has sufficient knowledge to provide the representations and may need to modify the letter to reflect the change in management", "The new CEO''s signature is invalid and the auditor must obtain the resigned CEO''s signature instead", "Management turnover has no effect on the representation letter because the representations relate to the entity rather than the individual"]'::jsonb, 1, 'Under AU-C 580.A3, the auditor should consider whether the individuals signing the representation letter have appropriate knowledge. When a new CEO did not oversee the fiscal year, the auditor should evaluate that person''s knowledge and may modify the letter or seek additional representations from other knowledgeable personnel. Choice D is incorrect because the competence and knowledge of the signer are relevant — the representations do relate to specific knowledge about the period covered.', 'medium', 3),

-- Q2: easy / L1 — Why representations must be written rather than oral
(1, 'Written Representations', 'Under AU-C 580, why must management representations be in written form rather than oral?', '["Written representations reduce the possibility of misunderstandings between management and the auditor", "Written representations are more persuasive than external confirmations from third parties", "Written representations eliminate the need for the auditor to perform additional corroborative procedures", "Written representations transfer legal liability for the financial statements from the auditor to management"]'::jsonb, 0, 'Under AU-C 580.04, written representations are required because they reduce the possibility of misunderstandings between the auditor and management. Putting representations in writing formalizes management''s acknowledgments and makes them more definitive than oral statements. Choice B is incorrect because written representations are actually among the least persuasive forms of evidence — external confirmations from third parties are generally more reliable.', 'easy', 1),

-- Q3: medium / L2 — Representation about uncorrected misstatements
(1, 'Written Representations', 'Baxter & Reed CPA is completing the audit of Lakeshore Manufacturing for the year ended December 31, 2025. The audit team identified $18,000 in uncorrected misstatements that management determined were immaterial individually and in aggregate. The auditor requests written representations about these misstatements. Under AU-C 580, the representation letter should state that management:', '["Has corrected all identified misstatements in the financial statements before issuance", "Has obtained the auditor''s written approval to omit adjustments for the identified misstatements", "Believes the uncorrected misstatements are immaterial individually and in aggregate to the financial statements as a whole", "Will correct the identified misstatements in the subsequent reporting period"]'::jsonb, 2, 'Under AU-C 580.11, the representation letter should include management''s acknowledgment that the effects of uncorrected misstatements are immaterial, individually and in aggregate, to the financial statements as a whole. A summary of such items should be attached to the letter. Choice A is incorrect because the question specifies management chose not to correct the misstatements — the representation addresses the immateriality assessment, not a promise to correct them.', 'medium', 2),

-- Q4: easy / L1 — Addressee of the representation letter
(1, 'Written Representations', 'Under AU-C 580, the management representation letter should be addressed to:', '["The entity''s board of directors or audit committee", "The Securities and Exchange Commission", "The entity''s external legal counsel", "The auditor performing the engagement"]'::jsonb, 3, 'Under AU-C 580.15, the management representation letter should be addressed to the auditor. The letter is a communication from management to the engagement team confirming specific matters discussed during the audit. Choice A is incorrect because while the board or audit committee has governance responsibilities, the representation letter is directed to the auditor as the recipient of management''s confirmations.', 'easy', 1),

-- Q5: hard / L4 — Evaluating refusal of specific required representation
(1, 'Written Representations', 'Thornberry & Associates is auditing Cascade Systems Inc. for the year ended December 31, 2025. Management provides the written representation letter but refuses to include a representation about the completeness of related-party transactions, citing competitive sensitivity. Management is willing to provide all other required representations. The engagement partner must evaluate the appropriate response. Under AU-C 580, the auditor should:', '["Treat the refusal as a scope limitation and evaluate the effect on the auditor''s report, which may result in a qualified opinion or disclaimer of opinion", "Accept all other representations and note the omission in the audit documentation without affecting the report", "Issue an unmodified opinion provided that alternative procedures yield sufficient evidence about related-party transactions", "Withdraw from the engagement immediately because any refusal to provide a required representation mandates withdrawal"]'::jsonb, 0, 'Under AU-C 580.19-.20, if management refuses to provide one or more requested written representations, the auditor should discuss the matter with management, reevaluate management''s integrity, and determine the effect on the auditor''s report. A refusal to provide a required representation is a scope limitation that may lead to a qualified opinion or disclaimer. Choice C is incorrect because alternative procedures cannot overcome the scope limitation created by management''s refusal to provide a required representation.', 'hard', 4),

-- Q6: medium / L2 — Representation about noncompliance with laws and regulations
(1, 'Written Representations', 'Franklin & Moore CPA is finalizing the audit of Redwood Pharmaceuticals for the year ended December 31, 2025. During the engagement, the team identified no instances of noncompliance with laws and regulations. The engagement partner is drafting the representation letter. Under AU-C 580, the representation regarding noncompliance should state that management has:', '["Warranted that no future noncompliance with laws and regulations will occur", "Confirmed that the auditor tested all applicable laws and regulations and found no violations", "Disclosed to the auditor all known instances of noncompliance or suspected noncompliance with laws and regulations whose effects should be considered in preparing the financial statements", "Certified that the entity has been in full compliance with all laws and regulations in every applicable jurisdiction"]'::jsonb, 2, 'Under AU-C 580.11, management should represent that it has disclosed to the auditor all known instances of noncompliance or suspected noncompliance with laws and regulations whose effects should be considered when preparing the financial statements. Choice D is incorrect because the representation concerns disclosure of known noncompliance, not a certification of total compliance — management cannot certify compliance with every law in every jurisdiction.', 'medium', 2),

-- Q7: easy / L1 — Written representations as necessary audit evidence
(1, 'Written Representations', 'Under AU-C 580, written representations from management are classified as which type of audit evidence?', '["Corroborative evidence that enhances external confirmations received from third parties", "Necessary audit evidence that the auditor is required to obtain in every audit engagement", "Persuasive evidence that ranks above external confirmations in the reliability hierarchy", "Supplemental evidence that the auditor may request at professional discretion"]'::jsonb, 1, 'Under AU-C 580.04, written representations are necessary information that the auditor requires in connection with the audit of the entity''s financial statements. They are required in every audit — not optional. Choice D is incorrect because AU-C 580 mandates the representation letter; it is not discretionary. Failure to obtain required representations is a scope limitation.', 'easy', 1),

-- Q8: medium / L2 — Representation about accounting policy selection
(1, 'Written Representations', 'Sullivan & Park CPA is auditing Crestwood Retail Group for the year ended December 31, 2025. During the engagement, the auditor notes that Crestwood changed its revenue recognition method for gift card breakage estimates. The auditor requests specific representations about accounting policies. Under AU-C 580, management should represent that:', '["The auditor approved the selection of all significant accounting policies applied during the year", "The entity''s accounting policies conform to the practices of the largest competitor in the retail industry", "Accounting policies were selected to maximize reported net income for the fiscal year", "The selection and application of accounting policies are appropriate for the entity''s applicable financial reporting framework"]'::jsonb, 3, 'Under AU-C 580.10-.11, management should represent that the financial statements are prepared in accordance with the applicable financial reporting framework, which includes appropriate selection and application of accounting policies. Choice A is incorrect because the auditor does not approve management''s accounting policy selections — management is responsible for selecting policies, and the auditor evaluates their appropriateness.', 'medium', 2),

-- Q9: hard / L4 — Evaluating discovered side agreement contradicting representations
(1, 'Written Representations', 'During the audit of Prism Analytics Corp. for the year ended December 31, 2025, the engagement team at Fielding & Associates obtains a management representation stating that no side agreements exist with the entity''s top three customers. However, the auditor discovers an unsigned draft agreement during inspection of the CFO''s files that appears to grant extended payment terms to a major customer. The engagement partner must evaluate the situation. Under AU-C 580, the most appropriate response is to:', '["Accept the written representation because unsigned drafts are not legally binding agreements", "Investigate the discrepancy by performing additional procedures and reassess the reliability of management''s representations overall", "Immediately issue an adverse opinion due to management''s material misrepresentation", "Require management to revise the representation letter to acknowledge the draft agreement without performing further investigation"]'::jsonb, 1, 'Under AU-C 580.17-.18, if the auditor identifies information that is inconsistent with written representations, the auditor should perform additional procedures to resolve the matter and reconsider the reliability of other representations. The auditor must exercise professional skepticism. Choice A is incorrect because even an unsigned draft may indicate an arrangement that contradicts management''s representation — the auditor cannot dismiss it based solely on the document''s unsigned status.', 'hard', 4),

-- Q10: easy / L1 — Primary purpose of written representations
(1, 'Written Representations', 'What is the primary purpose of obtaining written representations from management during an audit?', '["To confirm management''s responsibility for the financial statements and its acknowledgment of providing the auditor with complete information", "To transfer the auditor''s responsibility for detecting material misstatements to management", "To provide the auditor with a legal defense against future litigation by the entity", "To document management''s agreement with the auditor''s selected materiality thresholds"]'::jsonb, 0, 'Under AU-C 580.02-.03, the primary purpose of written representations is to confirm that management acknowledges its responsibility for the financial statements and has provided the auditor with all relevant information and access. Choice B is incorrect because written representations do not transfer the auditor''s responsibilities — the auditor retains responsibility for forming an opinion based on sufficient appropriate evidence.', 'easy', 1),

-- Q11: medium / L3 — Effect of omitting going concern representation
(1, 'Written Representations', 'Aldridge & Tate CPA is completing the audit of Pinnacle Staffing Solutions for the year ended December 31, 2025. The company has reported recurring losses and negative cash flows over the past three years. When preparing the representation letter, the CFO omits any representation about management''s assessment of the entity''s ability to continue as a going concern. What is the most likely effect of this omission on the auditor''s evaluation?', '["The omission has no effect because going concern representations are optional under AU-C 580", "The auditor should add the going concern representation to the letter and sign it on management''s behalf", "The auditor should discuss the omission with management and evaluate whether the missing representation constitutes a scope limitation", "The omission automatically requires the auditor to add a going concern emphasis-of-matter paragraph to the report"]'::jsonb, 2, 'Under AU-C 580.19, if management does not provide a requested representation, the auditor should discuss the matter with management and evaluate the implications. When going concern conditions exist, a representation about management''s plans is particularly important. The omission may constitute a scope limitation. Choice A is incorrect because representations about going concern are expected when conditions raising doubt exist, and their omission is not without consequence.', 'medium', 3),

-- Q12: medium / L3 — Verbal contradiction of signed estimate representation
(1, 'Written Representations', 'Morgan & Reeves CPA is auditing Frontier Logistics Corp. for the year ended December 31, 2025. Management signs the representation letter stating that significant assumptions used in accounting estimates are reasonable. However, the CFO verbally tells the engagement partner that the allowance for doubtful accounts may be understated by $250,000 but declines to adjust. What is the most likely effect on the auditor''s assessment?', '["The verbal statement has no effect because the signed representation letter supersedes all oral communications", "The auditor should disregard the verbal comment because it was not submitted in writing", "The auditor should accept the signed representation and document the verbal conversation for the file only", "The auditor should evaluate whether the verbal contradiction makes the written representation unreliable and consider the effect of the potential $250,000 understatement on the audit opinion"]'::jsonb, 3, 'Under AU-C 580.17-.18, when the auditor becomes aware of information contradicting a written representation, the auditor should perform additional procedures and reconsider the reliability of other representations. A verbal admission from the CFO that an estimate may be materially understated directly contradicts the signed letter. Choice A is incorrect because a signed letter does not override contradictory evidence — the auditor must exercise professional skepticism regardless of the letter''s signed status.', 'medium', 3),

-- Q13: medium / L2 — Representation about completeness of litigation and claims
(1, 'Written Representations', 'Harper & Sinclair CPA is auditing Trident Defense Solutions for the year ended December 31, 2025. The attorney''s letter confirms two pending lawsuits, but the auditor has learned through inquiry that a potential environmental claim is being assessed internally. The auditor drafts the representation letter. Under AU-C 580, the litigation-related representation should state that management has:', '["Resolved all pending litigation prior to the date of the auditor''s report", "Disclosed all known litigation, claims, and assessments whose effects should be considered when preparing the financial statements", "Obtained legal opinions confirming that no material losses will result from any pending litigation", "Disclosed only litigation that has been formally filed in court as of the balance sheet date"]'::jsonb, 1, 'Under AU-C 580.11, the representation letter should include management''s acknowledgment that it has disclosed all known litigation, claims, and assessments whose effects should be considered in the financial statements. This includes potential claims being assessed, not just formally filed lawsuits. Choice D is incorrect because the representation encompasses all known claims and assessments, not only those formally filed in court.', 'medium', 2),

-- Q14: hard / L4 — Evaluating when CFO refuses to sign
(1, 'Written Representations', 'During the audit of Veridian Healthcare Inc. for the year ended December 31, 2025, the engagement partner at Caldwell & Associates obtains the management representation letter. The CEO signs the letter, but the CFO refuses to sign, citing disagreement with the company''s inventory valuation methodology. Both executives are considered members of management with appropriate responsibilities. The engagement partner must evaluate the appropriate response. Under AU-C 580, the auditor should:', '["Accept the letter with only the CEO''s signature because one executive''s signature is sufficient under all circumstances", "Issue an unmodified opinion because the CEO is the highest-ranking officer in the organization", "Evaluate whether the CFO''s refusal and stated reason affect the reliability of the representations and consider the implications for the audit opinion", "Withdraw from the engagement immediately because both requested signatures are required without exception"]'::jsonb, 2, 'Under AU-C 580.19-.20, if management does not provide requested representations, the auditor should discuss the reasons, reevaluate management''s integrity, and determine the effect on the audit opinion. The CFO''s refusal based on a substantive accounting disagreement is significant and warrants further investigation. Choice A is incorrect because the CFO''s stated disagreement over inventory valuation suggests a potential issue that cannot be dismissed simply because the CEO signed.', 'hard', 4),

-- Q15: medium / L2 — Representation about access to records and personnel
(1, 'Written Representations', 'Bennett & Cruz CPA is completing the audit of Solaris Technologies for the year ended December 31, 2025. The engagement partner prepares the management representation letter and considers which assertions about access should be included. Under AU-C 580, management should represent that it has provided the auditor with:', '["Access only to records that management considers directly relevant to the financial statement line items tested", "Access limited to financial accounting records, specifically excluding operational and governance documentation", "Unlimited physical access to all company premises including classified research facilities", "Access to all information that management believes is relevant to the preparation of the financial statements, including additional information requested and access to persons within the entity"]'::jsonb, 3, 'Under AU-C 580.10-.11, management should represent that it has provided the auditor with all information relevant to the preparation and fair presentation of the financial statements, any additional information requested, and unrestricted access to persons within the entity. Choice A is incorrect because management should not unilaterally limit access to only those records it considers relevant — the auditor determines what information is needed.', 'medium', 2),

-- Q16: medium / L3 — Additional entity-specific representations beyond required list
(1, 'Written Representations', 'During the audit of Sterling Electronics Corp. for the year ended December 31, 2025, the engagement partner at Whitmore & Klein notes that Sterling maintains $8.5 million in inventory held on consignment at third-party warehouses. The partner evaluates whether the standard representation letter adequately addresses this situation. What is the most likely effect on the representation letter?', '["The auditor should request an additional representation specific to consignment inventory because AU-C 580 permits tailoring the letter with representations relevant to the entity beyond those specifically required by the standard", "The standard completeness representation is sufficient because it inherently covers all assets including consigned inventory at third-party locations", "The auditor should send confirmations to the warehouses instead of modifying the representation letter for consignment", "Additional representations are prohibited because AU-C 580 specifies a fixed and exhaustive list that the auditor cannot modify"]'::jsonb, 0, 'Under AU-C 580.A1-.A2 and .13, the auditor may request additional written representations beyond those specifically required by AU-C 580. When the entity has unique circumstances such as significant consignment inventory, the auditor should tailor the letter to address entity-specific risks. Choice D is incorrect because AU-C 580 explicitly contemplates additional representations — the standard''s list is not exhaustive and should be supplemented based on engagement circumstances.', 'medium', 3),

-- Q17: medium / L2 — Representation about management's intent for asset classification
(1, 'Written Representations', 'Palmer & Whitfield CPA is auditing Meridian Capital Corp. for the year ended December 31, 2025. Meridian holds $12 million in debt securities classified as held-to-maturity. The auditor considers what written representation is needed regarding management''s intent. Under AU-C 580, the auditor should obtain a representation that management:', '["Will liquidate the held-to-maturity portfolio if interest rates increase by more than 200 basis points", "Has the intent and ability to hold the debt securities to maturity as classified in the financial statements", "Has obtained board approval for the classification of each individual debt security in the portfolio", "Will reclassify the securities to available-for-sale if their fair value declines below amortized cost"]'::jsonb, 1, 'Under AU-C 580.11 and AU-C 540, when financial statement assertions depend on management''s intent, the auditor should obtain a written representation confirming that intent. Held-to-maturity classification requires both the intent and ability to hold securities to maturity. Choice A is incorrect because this describes a contingent sale plan that would actually undermine the held-to-maturity classification rather than support it.', 'medium', 2),

-- Q18: medium / L3 — Effect of late representation letter on report dating
(1, 'Written Representations', 'Calloway & Drake CPA completes fieldwork for the audit of Greystone Properties LLC on February 20, 2026, and plans to date the auditor''s report on that date. However, management does not provide the signed representation letter until March 5, 2026. The engagement partner must evaluate the effect on the audit. What is the most likely consequence of the delayed representation letter?', '["The auditor should issue the report dated February 20 and document the delay in the working papers as an administrative matter", "The delayed letter has no effect on the audit because the fieldwork was completed on time", "The auditor must restart all fieldwork from the beginning to cover the entire additional period through March 5", "The auditor should either extend subsequent events procedures to the representation letter date or obtain the letter dated as of the planned report date of February 20"]'::jsonb, 3, 'Under AU-C 580.15, the representation letter should be dated no earlier than the date of the auditor''s report. If the letter is dated later than the planned report date, the auditor must either extend subsequent events procedures to cover the gap or request that management date the letter as of the original report date. Choice A is incorrect because the auditor cannot issue the report before obtaining the required representation letter — it is a precondition for issuing the opinion.', 'medium', 3),

-- Q19: easy / L1 — Subsequent events representation content
(1, 'Written Representations', 'Under AU-C 580, the management representation letter should include a representation about subsequent events. This representation typically states that:', '["No events of any kind have occurred after the balance sheet date", "The auditor is solely responsible for identifying and evaluating all subsequent events", "All events occurring between the balance sheet date and the date of the representation letter that require adjustment or disclosure have been disclosed to the auditor", "Subsequent events are relevant only if they result in pending litigation against the entity"]'::jsonb, 2, 'Under AU-C 580.11, the representation letter should include management''s acknowledgment that it has informed the auditor of all subsequent events occurring through the representation letter date that require adjustment or disclosure under the applicable financial reporting framework. Choice A is incorrect because the representation does not claim no events occurred — rather, it confirms that events requiring adjustment or disclosure have been communicated to the auditor.', 'easy', 1),

-- Q20: medium / L2 — Representation about completeness of information provided
(1, 'Written Representations', 'Garrison & Webb CPA is auditing Blackthorn Manufacturing for the year ended December 31, 2025. The engagement partner is finalizing the representation letter and asks the controller to include a representation about completeness of information. Under AU-C 580, management should represent that it has:', '["Reviewed every transaction processed during the fiscal year and independently verified its accuracy", "Provided the auditor with all documents that bear the company''s official letterhead", "Shared only information that management has determined to be relevant to the financial statements", "Provided the auditor with all relevant information and access as agreed upon in the terms of the audit engagement"]'::jsonb, 3, 'Under AU-C 580.10-.11, management should represent that it has provided the auditor with all information relevant to the preparation and fair presentation of the financial statements, as agreed upon in the engagement letter terms. This is one of the fundamental representations required in every audit. Choice C is incorrect because management should not unilaterally limit what it shares — it must provide all relevant information, not just what it deems relevant.', 'medium', 2),

-- Q21: medium / L3 — Omission of material subsequent event from signed rep letter
(1, 'Written Representations', 'Harwell & Price CPA is auditing Apex Digital Services for the year ended December 31, 2025. The auditor''s report is dated March 10, 2026. On March 8, management learns that a major customer representing 15% of accounts receivable filed for bankruptcy. The CFO signs the representation letter on March 10 without mentioning this event. What is the most likely effect on the auditor''s evaluation?', '["The omission raises concerns about the reliability of the representation letter because management should have disclosed a material subsequent event occurring before the letter date", "The omission has no effect because the customer bankruptcy occurred after the balance sheet date and is a Type II event only", "The auditor should accept the letter because individual customer bankruptcies are ordinary business events requiring no special disclosure", "The auditor should issue the report as planned and address the bankruptcy disclosure in the subsequent audit cycle"]'::jsonb, 0, 'Under AU-C 580.11 and AU-C 560, management should disclose all subsequent events requiring adjustment or disclosure through the date of the representation letter. A major customer bankruptcy affecting 15% of receivables is clearly material and should have been disclosed. The omission raises questions about management''s integrity and the reliability of other representations. Choice B is incorrect because even Type II events must be disclosed in the notes if material, and management must inform the auditor of such events.', 'medium', 3),

-- Q22: hard / L3 — Group audit representation letter considerations
(1, 'Written Representations', 'Waverly & Associates is the group engagement partner for the consolidated audit of Apex Holdings Corp. for the year ended December 31, 2025. Apex has three significant subsidiaries, each audited by different component auditors. The engagement partner is determining the appropriate approach to management representations for the group audit. Under AU-C 580 and AU-C 600, which factor most likely affects the group auditor''s approach to written representations?', '["The group auditor should obtain representation letters only from the parent company because subsidiary representations are exclusively the component auditors'' responsibility", "The group auditor should determine whether to obtain representations from component management based on the nature and extent of the group auditor''s involvement with the component financial information", "The group auditor must obtain identical representation letters from management of every entity in the group regardless of each component''s materiality", "The group auditor should rely exclusively on the component auditors'' representation letters without seeking any representations from group management"]'::jsonb, 1, 'Under AU-C 600.40-.41 and AU-C 580, the group engagement partner should obtain representations from group management and determine the need for component management representations based on involvement with components. The approach is risk-based, considering the nature and significance of each component. Choice A is incorrect because the group auditor may also need representations from component management depending on the group auditor''s level of involvement with the component''s financial information.', 'hard', 3),

-- Q23: medium / L3 — Representation about side agreements and informal arrangements
(1, 'Written Representations', 'Kelley & Archer CPA is auditing Coastal Freight Lines for the year ended December 31, 2025. The auditor discovers that Coastal has informal volume rebate arrangements with two of its largest shipping partners that are not documented in the formal contracts. The auditor evaluates what additional representations may be needed. What is the most likely implication for the management representation letter?', '["No additional representations are needed because informal arrangements are outside the scope of audit evidence", "The auditor should document the arrangements in the working papers without seeking a management representation", "The auditor should request a specific representation that management has disclosed all significant arrangements, including side agreements and informal understandings, whether documented or not", "The auditor should rely on the standard completeness representation without requesting additional specificity about informal arrangements"]'::jsonb, 2, 'Under AU-C 580.13, the auditor may request additional written representations tailored to the entity''s circumstances. When the auditor discovers informal arrangements not captured in formal contracts, requesting a specific representation about side agreements and undocumented arrangements strengthens the audit evidence. Choice D is incorrect because the standard completeness representation may not adequately cover informal arrangements — a specific representation draws management''s explicit attention to these items.', 'medium', 3),

-- Q24: easy / L1 — Representations do not substitute for other evidence
(1, 'Written Representations', 'Under AU-C 580, which statement accurately describes written representations from management?', '["Are the most persuasive form of audit evidence available to the auditor", "Eliminate the need for the auditor to perform corroborative substantive procedures", "Do not substitute for other audit evidence that the auditor expects to obtain", "Are required only when the auditor identifies a material misstatement during fieldwork"]'::jsonb, 2, 'Under AU-C 580.04, written representations are necessary information but do not provide sufficient appropriate audit evidence on their own about the matters they address. They complement, rather than replace, other evidence the auditor is expected to obtain. Choice A is incorrect because written representations are among the least persuasive forms of evidence — they are internal representations that lack the reliability of external or directly obtained evidence.', 'easy', 1),

-- Q25: medium / L2 — Representation about completeness of contingent liabilities
(1, 'Written Representations', 'Mitchell & Drake CPA is auditing Granite Ridge Construction for the year ended December 31, 2025. The entity is involved in a contract dispute with a subcontractor over $430,000 in claimed damages. Management''s legal counsel has assessed the likelihood of loss as reasonably possible. The auditor requests a written representation from management. Under AU-C 580, the representation should confirm that management has:', '["Disclosed all known contingent liabilities and provided its assessment of the likelihood and estimated amount of each contingency", "Obtained an assurance from legal counsel that the entity will prevail in the contract dispute", "Established a loss reserve equal to the full $430,000 in claimed damages", "Deferred disclosure of the contingency until the litigation is fully resolved"]'::jsonb, 0, 'Under AU-C 580.11, the representation letter should include management''s acknowledgment that it has disclosed all known contingencies. For a reasonably possible loss, disclosure in the notes is required under ASC 450-20. The representation ensures management has not omitted any contingent liabilities from the financial statements or disclosures. Choice D is incorrect because ASC 450 requires disclosure of reasonably possible contingencies — deferral until resolution would violate the reporting framework.', 'medium', 2),

-- Q26: easy / L1 — Explicit written representations defined
(1, 'Written Representations', 'Under AU-C 580, what are explicit written representations?', '["Representations that are implied through management''s approval of the draft financial statements", "Specific written statements made by management in the representation letter at the auditor''s request addressing particular matters", "Verbal confirmations from management that the auditor transcribes and documents in the working papers", "Representations that are embedded within the footnotes and disclosures of the financial statements"]'::jsonb, 1, 'Under AU-C 580.06, explicit written representations are specific statements provided by management in writing, typically in the management representation letter, addressing matters that the auditor considers important to the audit. They are distinguished from implicit representations. Choice A is incorrect because implied representations arise from management''s actions, not from explicit written statements — approval of the financial statements may constitute an implicit representation, not an explicit one.', 'easy', 1),

-- Q27: hard / L4 — First-year audit with comparative financial statements
(1, 'Written Representations', 'Prescott & Hart CPA is performing a first-year audit of Summit Ridge Investments for the year ended December 31, 2025. The predecessor auditor issued an unmodified opinion on the 2024 financial statements. Summit Ridge presents comparative financial statements for both 2024 and 2025. The engagement partner at Prescott & Hart must evaluate the appropriate scope of the management representation letter. Under AU-C 580, the auditor should:', '["Limit the representation letter to the current year only because the predecessor auditor already obtained representations covering the prior period", "Request the predecessor auditor''s copy of the prior-year representation letter and include it in the current audit file without modification", "Require management to obtain a new representation letter from the predecessor auditor covering the prior period", "Obtain representations from management covering both the current and prior periods presented in the comparative financial statements"]'::jsonb, 3, 'Under AU-C 580.14-.15, when comparative financial statements are presented, management''s representations should cover all periods referred to in the auditor''s report. Even though the predecessor audited the prior year, the current auditor needs representations about the prior-period figures as presented. Choice A is incorrect because the predecessor''s prior-year representations do not satisfy the current auditor''s obligation — management must provide current representations covering all periods presented.', 'hard', 4),

-- Q28: easy / L2 — Representation about management's responsibility for financial statements
(1, 'Written Representations', 'During the audit of Oakmont Financial Corp. for the year ended December 31, 2025, the engagement partner at Lawson & Associates prepares the management representation letter. Management asks what specific responsibility they must acknowledge in the letter. Under AU-C 580, management should represent that:', '["The auditor is primarily responsible for the accuracy and completeness of the financial statements", "Management is responsible for the preparation and fair presentation of the financial statements in accordance with the applicable financial reporting framework", "The board of directors bears sole responsibility for financial reporting matters", "Responsibility for the financial statements is shared equally between management and the external auditor"]'::jsonb, 1, 'Under AU-C 580.10-.11, a fundamental written representation requires management to acknowledge its responsibility for the preparation and fair presentation of the financial statements in accordance with the applicable financial reporting framework. This is consistent with the premise of an audit. Choice D is incorrect because responsibility for the financial statements rests with management, not jointly with the auditor — the auditor is responsible for the audit opinion, not the financial statements.', 'easy', 2),

-- Q29: easy / L1 — Required for every audit engagement
(1, 'Written Representations', 'Under AU-C 580, in which type of engagement is a written management representation letter required?', '["Every audit of financial statements regardless of the entity''s size or public reporting status", "Only audits of publicly traded companies subject to SEC reporting requirements", "Only audits where the auditor identifies material misstatements during fieldwork", "Only audits of entities with total annual revenues exceeding $10 million"]'::jsonb, 0, 'Under AU-C 580.09-.10, the auditor is required to request written representations from management for every audit of financial statements. The requirement applies regardless of entity size, industry, or public reporting status. Choice B is incorrect because the requirement under AU-C 580 applies to all audits conducted under generally accepted auditing standards, not only those of publicly traded companies.', 'easy', 1),

-- Q30: hard / L4 — Evaluating representations when management lacks expertise
(1, 'Written Representations', 'During the audit of Obsidian Aerospace Corp. for the year ended December 31, 2025, the engagement team at Doyle & Associates requests a written representation about the completeness of environmental liabilities. The CEO states that management lacks the technical expertise to fully identify all potential environmental obligations and has not engaged environmental specialists. The engagement partner must evaluate the implications. Under AU-C 580, the auditor should:', '["Evaluate whether management''s lack of knowledge raises doubt about the completeness of environmental liabilities and consider recommending that management engage a specialist before providing the representation", "Accept the representation as written because management can only represent matters within its actual knowledge", "Draft the environmental liability representation on management''s behalf and request that the CEO sign it", "Exclude the environmental liability representation entirely and issue the report without addressing the matter"]'::jsonb, 0, 'Under AU-C 580.A8 and AU-C 500, when management acknowledges lacking expertise to identify potential liabilities, the auditor should evaluate the implications for the completeness assertion. The auditor may recommend that management engage a specialist to identify obligations before making representations. Choice B is incorrect because management''s lack of knowledge does not excuse the auditor from obtaining sufficient appropriate evidence — if management cannot provide adequate representations, it may indicate a scope limitation.', 'hard', 4)
;

COMMIT;
